<?php
use App\Http\Controllers\Admin\EventController; use App\Http\Controllers\Admin\QuestionModerationController; use App\Http\Controllers\Api\PublicEventController; use Illuminate\Support\Facades\Route;
Route::prefix('e/{code}')->group(function(){Route::get('/',[PublicEventController::class,'show']);Route::get('/qr',[PublicEventController::class,'qr']);Route::get('/questions',[PublicEventController::class,'questions']);Route::post('/questions',[PublicEventController::class,'storeQuestion'])->middleware('throttle:questions');Route::post('/questions/{question}/vote',[PublicEventController::class,'vote'])->middleware('throttle:votes');});
Route::middleware(['web','auth','event.admin'])->prefix('admin')->group(function(){Route::apiResource('events',EventController::class)->except(['show']);Route::get('events/{event}/urls',[EventController::class,'urls']);Route::get('events/{event}/questions',[QuestionModerationController::class,'index']);Route::patch('events/{event}/questions/{question}',[QuestionModerationController::class,'update']);});
